from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class MeasurementsPMV1(SchemaObject):
    id = SchemaField(name="id")
    abbreviation = SchemaField(name="abbreviation")
    dimension_dist_name = SchemaField(name="dimensionDistName")
    start_times = SchemaField(name="startTimes")

    def __init__(self, id, abbreviation, dimension_dist_name, start_times):
        self.id = id
        self.abbreviation = abbreviation
        self.dimension_dist_name = dimension_dist_name
        self.start_times = start_times
        super(MeasurementsPMV1, self).__init__()
